Write the application service of DebitAccount.

Design:
{
 "context": "payments",
 "base_package": "com.bank.payments",
 "entities": [
  {
   "name": "PaymentOrder",
   "table": "payment_orders",
   "legacy_table": "ORDENES",
   "key": [
    "orderNumber",
    "companyId"
   ],
   "fields": [
    {
     "name": "orderNumber",
     "type": "integer(32,signed)",
     "column": "order_number",
     "legacy": "ORD_NUMERO"
    },
    {
     "name": "companyId",
     "type": "integer(32,signed)",
     "column": "company_id",
     "legacy": "ORD_EMPRESA"
    },
    {
     "name": "status",
     "type": "text(fixed,1,iso8859-1)",
     "column": "status",
     "legacy": "ORD_ESTADO"
    },
    {
     "name": "orderValue",
     "type": "decimal(11,2,signed)",
     "column": "order_value",
     "legacy": "ORD_VALOR"
    },
    {
     "name": "movementNumber",
     "type": "integer(64,signed)",
     "column": "movement_number",
     "legacy": "ORD_MOVIM"
    },
    {
     "name": "commission",
     "type": "decimal(5,2,signed)",
     "column": "commission",
     "legacy": "ORD_COMIS"
    }
   ]
  },
  {
   "name": "Account",
   "table": "accounts",
   "legacy_table": "CUENTAS",
   "key": [
    "accountNumber"
   ],
   "fields": [
    {
     "name": "accountNumber",
     "type": "integer(64,signed)",
     "column": "account_number",
     "legacy": "CTA_NUMERO"
    },
    {
     "name": "accountType",
     "type": "text(fixed,3,iso8859-1)",
     "column": "account_type",
     "legacy": "CTA_TIPO"
    },
    {
     "name": "balance",
     "type": "decimal(13,2,signed)",
     "column": "balance",
     "legacy": "CTA_SALDO"
    },
    {
     "name": "status",
     "type": "text(fixed,1,iso8859-1)",
     "column": "status",
     "legacy": "CTA_ESTADO"
    }
   ]
  }
 ],
 "ports": [
  {
   "name": "OrderRepository",
   "entity": "PaymentOrder",
   "legacy_program": null,
   "methods": [
    {
     "name": "findByKeyForUpdate",
     "description": "Reads the order by company and order number, locking it for update (READ FILE ORDENES UPDATE). Empty when not found.",
     "inputs": [
      {
       "name": "orderNumber",
       "type": "integer(32,signed)",
       "column": null,
       "legacy": "ORD_NUMERO"
      },
      {
       "name": "companyId",
       "type": "integer(32,signed)",
       "column": null,
       "legacy": "ORD_EMPRESA"
      }
     ],
     "returns": "PaymentOrder",
     "legacy_output": null
    },
    {
     "name": "markPaid",
     "description": "Sets the order status to paid ('G') and stores the movement number and the commission charged (REWRITE ORDENES).",
     "inputs": [
      {
       "name": "orderNumber",
       "type": "integer(32,signed)",
       "column": null,
       "legacy": "ORD_NUMERO"
      },
      {
       "name": "companyId",
       "type": "integer(32,signed)",
       "column": null,
       "legacy": "ORD_EMPRESA"
      },
      {
       "name": "movementNumber",
       "type": "integer(64,signed)",
       "column": null,
       "legacy": "ORD_MOVIM"
      },
      {
       "name": "commission",
       "type": "decimal(5,2,signed)",
       "column": null,
       "legacy": "ORD_COMIS"
      }
     ],
     "returns": "int",
     "legacy_output": null
    }
   ]
  },
  {
   "name": "AccountRepository",
   "entity": "Account",
   "legacy_program": null,
   "methods": [
    {
     "name": "findByNumberForUpdate",
     "description": "Reads the account by number, locking it for update (READ FILE CUENTAS UPDATE). Empty when not found.",
     "inputs": [
      {
       "name": "accountNumber",
       "type": "integer(64,signed)",
       "column": null,
       "legacy": "CTA_NUMERO"
      }
     ],
     "returns": "Account",
     "legacy_output": null
    },
    {
     "name": "updateBalance",
     "description": "Rewrites the account with the new balance (REWRITE CUENTAS).",
     "inputs": [
      {
       "name": "accountNumber",
       "type": "integer(64,signed)",
       "column": null,
       "legacy": "CTA_NUMERO"
      },
      {
       "name": "balance",
       "type": "decimal(13,2,signed)",
       "column": null,
       "legacy": "CTA_SALDO"
      }
     ],
     "returns": "int",
     "legacy_output": null
    }
   ]
  },
  {
   "name": "MovementGateway",
   "entity": null,
   "legacy_program": "PAGOMOV",
   "methods": [
    {
     "name": "registerMovement",
     "description": "Registers the payment movement for the order and returns the movement number (LINK PAGOMOV).",
     "inputs": [
      {
       "name": "orderNumber",
       "type": "integer(32,signed)",
       "column": null,
       "legacy": "MOV_ORDEN"
      }
     ],
     "returns": "long",
     "legacy_output": "MOV_NUMERO"
    }
   ]
  }
 ],
 "use_cases": [
  {
   "name": "DebitAccount",
   "description": "Debits the amount from the customer account (legacy PAGODEB). Validates existence, type, active status and sufficient balance, and answers with the response code: 00 debited, 10 inactive, 20 insufficient balance, 30 not found, 40 type mismatch. The response code is data, not an exception. The balance is rewritten only when the debit succeeds.",
   "rules": [
    "RULE-001",
    "RULE-002",
    "RULE-003",
    "RULE-004",
    "RULE-005"
   ],
   "inputs": [
    {
     "name": "accountNumber",
     "type": "integer(64,signed)",
     "column": null,
     "legacy": "DEB-CUENTA"
    },
    {
     "name": "accountType",
     "type": "text(fixed,3,iso8859-1)",
     "column": null,
     "legacy": "DEB-TIPO"
    },
    {
     "name": "amount",
     "type": "decimal(13,2,signed)",
     "column": null,
     "legacy": "DEB-MONTO"
    }
   ],
   "outputs": [
    {
     "name": "responseCode",
     "type": "text(fixed,2,iso8859-1)",
     "column": null,
     "legacy": "DEB-RESP"
    }
   ],
   "errors": [],
   "ports": [
    "AccountRepository"
   ],
   "http_method": "POST",
   "path": "/accounts/debit",
   "legacy_program": "PAGODEB",
   "unit_of_work": null,
   "legacy_message": "DEB-RESP"
  },
  {
   "name": "PayOrder",
   "description": "Pays a pending order: validates the input (order number, account type, channel, approval key), reads the order for update, checks it is pending and that the amount equals the order value, computes the commission (0 from 50,000; 1.00 on WEB; 2.50 otherwise), debits the account (DebitAccount) for value plus commission, registers the movement (PAGOMOV), marks the order as paid and commits. Any rejection happens before any write, so nothing is persisted. A rejection returns the legacy message.",
   "rules": [
    "RULE-009",
    "RULE-010",
    "RULE-011",
    "RULE-012",
    "RULE-013",
    "RULE-014",
    "RULE-015",
    "RULE-016",
    "RULE-017",
    "RULE-018",
    "RULE-019"
   ],
   "inputs": [
    {
     "name": "orderNumber",
     "type": "text(fixed,7,iso8859-1)",
     "column": null,
     "legacy": "ORDEN"
    },
    {
     "name": "companyId",
     "type": "integer(32,signed)",
     "column": null,
     "legacy": "EMPRESA"
    },
    {
     "name": "accountType",
     "type": "text(fixed,3,iso8859-1)",
     "column": null,
     "legacy": "TIPCTA"
    },
    {
     "name": "accountNumber",
     "type": "integer(64,signed)",
     "column": null,
     "legacy": "CUENTA"
    },
    {
     "name": "value",
     "type": "decimal(11,2,signed)",
     "column": null,
     "legacy": "VALOR"
    },
    {
     "name": "channel",
     "type": "text(fixed,3,iso8859-1)",
     "column": null,
     "legacy": "CANAL"
    },
    {
     "name": "approvalKey",
     "type": "text(fixed,6,iso8859-1)",
     "column": null,
     "legacy": "CLAVE"
    }
   ],
   "outputs": [
    {
     "name": "orderNumber",
     "type": "integer(32,signed)",
     "column": null,
     "legacy": "RORDEN"
    },
    {
     "name": "commission",
     "type": "decimal(5,2,signed)",
     "column": null,
     "legacy": "RCOMIS"
    },
    {
     "name": "movementNumber",
     "type": "integer(64,signed)",
     "column": null,
     "legacy": "RMOVIM"
    },
    {
     "name": "resultMessage",
     "type": "text(var,40,iso8859-1)",
     "column": null,
     "legacy": "RMENS"
    }
   ],
   "errors": [
    {
     "code": "INVALID_ORDER_NUMBER",
     "legacy_code": "-1",
     "message": "NUMERO DE ORDEN INVALIDO"
    },
    {
     "code": "ACCOUNT_TYPE_NOT_ALLOWED",
     "legacy_code": "-1",
     "message": "TIPO DE CUENTA NO PERMITIDO"
    },
    {
     "code": "CHANNEL_NOT_ALLOWED",
     "legacy_code": "-1",
     "message": "CANAL NO PERMITIDO"
    },
    {
     "code": "APPROVAL_KEY_REQUIRED",
     "legacy_code": "-1",
     "message": "CLAVE DE APROBACION REQUERIDA"
    },
    {
     "code": "ORDER_NOT_FOUND",
     "legacy_code": "-1",
     "message": "ORDEN NO EXISTE"
    },
    {
     "code": "ORDER_NOT_PENDING",
     "legacy_code": "-1",
     "message": "ORDEN NO ESTA PENDIENTE"
    },
    {
     "code": "AMOUNT_MISMATCH",
     "legacy_code": "-1",
     "message": "VALOR NO COINCIDE CON LA ORDEN"
    },
    {
     "code": "ACCOUNT_INACTIVE",
     "legacy_code": "-1",
     "message": "CUENTA INACTIVA"
    },
    {
     "code": "INSUFFICIENT_FUNDS",
     "legacy_code": "-1",
     "message": "SALDO INSUFICIENTE"
    },
    {
     "code": "INVALID_ACCOUNT",
     "legacy_code": "-1",
     "message": "CUENTA NO VALIDA"
    }
   ],
   "ports": [
    "OrderRepository",
    "AccountRepository",
    "MovementGateway"
   ],
   "http_method": "POST",
   "path": "/payment-orders/pay",
   "legacy_program": "PAGOORD",
   "unit_of_work": {
    "begins_at": 37,
    "commits_at": 172,
    "savepoints": [],
    "rollbacks": []
   },
   "legacy_message": "MENSAJE"
  },
  {
   "name": "StartPaymentOrderEntry",
   "description": "First entry to the payment order transaction: returns a blank form whose channel is pre-filled with WEB.",
   "rules": [
    "RULE-007"
   ],
   "inputs": [],
   "outputs": [
    {
     "name": "defaultChannel",
     "type": "text(fixed,3,iso8859-1)",
     "column": null,
     "legacy": "CANALO"
    }
   ],
   "errors": [],
   "ports": [],
   "http_method": "GET",
   "path": "/payment-orders/new",
   "legacy_program": "PAGOORD",
   "unit_of_work": {
    "begins_at": 37,
    "commits_at": 172,
    "savepoints": [],
    "rollbacks": []
   },
   "legacy_message": "MENSAJEO"
  },
  {
   "name": "DispatchPaymentOrderKey",
   "description": "Dispatches the function key pressed on the payment order screen: ENTER processes the payment, PF3 returns to the menu, any other key is rejected with TECLA NO VALIDA.",
   "rules": [
    "RULE-008"
   ],
   "inputs": [
    {
     "name": "functionKey",
     "type": "text(fixed,1,iso8859-1)",
     "column": null,
     "legacy": "EIBAID"
    }
   ],
   "outputs": [
    {
     "name": "action",
     "type": "text(var,20,iso8859-1)",
     "column": null,
     "legacy": "EIBAID"
    }
   ],
   "errors": [
    {
     "code": "INVALID_KEY",
     "legacy_code": "TECLA NO VALIDA",
     "message": "TECLA NO VALIDA"
    }
   ],
   "ports": [],
   "http_method": "POST",
   "path": "/payment-orders/keys",
   "legacy_program": "PAGOORD",
   "unit_of_work": {
    "begins_at": 37,
    "commits_at": 172,
    "savepoints": [],
    "rollbacks": []
   },
   "legacy_message": "MENSAJEO"
  },
  {
   "name": "SelectMenuOption",
   "description": "Routes the payment main menu option: 1 goes to payment order entry, 9 ends the session, any other option is rejected with OPCION NO VALIDA.",
   "rules": [
    "RULE-006"
   ],
   "inputs": [
    {
     "name": "option",
     "type": "text(fixed,1,iso8859-1)",
     "column": null,
     "legacy": "OPCIONI"
    }
   ],
   "outputs": [
    {
     "name": "destination",
     "type": "text(var,8,iso8859-1)",
     "column": null,
     "legacy": "PROGRAM"
    }
   ],
   "errors": [
    {
     "code": "INVALID_OPTION",
     "legacy_code": "OPCION NO VALIDA",
     "message": "OPCION NO VALIDA"
    }
   ],
   "ports": [],
   "http_method": "POST",
   "path": "/menu/options",
   "legacy_program": "PAGOMNU",
   "unit_of_work": null,
   "legacy_message": "MENSAJEO"
  }
 ],
 "decisions": [
  {
   "title": "Data moves to PostgreSQL with target names",
   "context": "The VSAM files ORDENES and CUENTAS hold the business data.",
   "decision": "Migrate them to the tables payment_orders and accounts with snake_case columns, keeping the legacy precision (decimal(11,2), decimal(13,2), decimal(5,2)). Order status codes stay P (pending) and G (paid); account status codes stay A (active) and I (inactive).",
   "consequences": "Record layouts and fillers disappear. Data migration must convert COMP-3 and DISPLAY fields to numeric columns."
  },
  {
   "title": "One transaction per payment, owned by the REST adapter",
   "context": "PAGOORD is pseudo-conversational. It reads the order and the account for update, rewrites both and the SYNCPOINT at line 172 confirms the work. Every rejection happens before the first write. All use cases that come from PAGOORD declare the same unit of work (begin at line 37, commit at line 172) with no savepoints and no rollback points.",
   "decision": "The REST adapter opens the transaction at the beginning of PayOrder and commits it on success. Any business rejection rolls it back. The reads use update locks (findByKeyForUpdate, findByNumberForUpdate). No UnitOfWork port is declared, because the legacy has no savepoints and rejects with a non-zero status.",
   "consequences": "Debit, movement registration and order update are atomic. If PAGOMOV or the order update fails after the debit, the debit is undone, as with the CICS syncpoint rollback. The navigation use cases (first entry, key dispatch) write no data, so their transaction is empty."
  },
  {
   "title": "Debit of PAGODEB reused as a use case",
   "context": "PAGOORD calls PAGODEB with LINK. In the traces PAGODEB runs for real: the CUENTAS balances change and it is not stubbed.",
   "decision": "The debit logic lives in the DebitAccount use case (rules 001-005) on top of AccountRepository. PayOrder invokes it in-process within its own transaction and maps the response code: 00 continue, 10 CUENTA INACTIVA, 20 SALDO INSUFICIENTE, any other CUENTA NO VALIDA.",
   "consequences": "PAGODEB is not a remote port. It is also exposed as POST /accounts/debit for other callers, where rejections are returned as response codes, as in the legacy."
  },
  {
   "title": "PAGOMOV is a port",
   "context": "PAGOMOV is not part of the inputs and its source is unavailable. The traces stub it and return MOV_NUMERO.",
   "decision": "Model it as MovementGateway (legacy_program PAGOMOV) with registerMovement(orderNumber) returning the movement number (legacy output MOV_NUMERO).",
   "consequences": "The adapter must be implemented against the real movement system. Tests replay it with the trace stubs."
  },
  {
   "title": "Rejections of PAGOORD are business errors with the legacy message",
   "context": "The traces show return status -1 with only the output MENSAJE on every rejection, and no other outputs.",
   "decision": "Each rejection is a business error with a stable code and the exact legacy message (legacy_code -1, message carried by MENSAJE). The REST adapter answers a 4xx with that message and no payment outputs.",
   "consequences": "The legacy sequence of checks is kept: order number, account type, channel, approval key, order read, pending status, amount, then debit."
  },
  {
   "title": "Screen concerns replaced by REST",
   "context": "BMS maps, commarea, function keys and pseudo-conversational RETURN TRANSID belong to the terminal technology.",
   "decision": "The conversation state (commarea) is dropped. The amount is received as a decimal with two decimals instead of the 11-digit screen field with implied decimals, so the NUMVAL(VALORI)/100 conversion is done by the adapter before the comparison with the order value. The menu, first entry and key dispatch rules are kept as small use cases (SelectMenuOption, StartPaymentOrderEntry, DispatchPaymentOrderKey) so that a thin UI can reproduce the navigation. The error display of rule 019 is the rejection message returned by PayOrder.",
   "consequences": "A client that is not a terminal can call PayOrder directly. The BMS formatting of the result (ZZZ,ZZ9.99 and Z(9)9) is a presentation concern and is not reproduced."
  }
 ],
 "masks": [],
 "infrastructure": [],
 "data_strategy": "migration"
}

Rules:
[
 {
  "id": "RULE-001",
  "name": "Debit rejected when account does not exist",
  "category": "validation",
  "priority": "P0",
  "statement": "A debit against an account number that is not on the CUENTAS file is rejected with response code '30' and the balance is not changed.",
  "condition": "READ of CUENTAS by DEB-CUENTA returns NOTFND",
  "action": "Set DEB-RESP = '30'; no debit is made.",
  "inputs": [
   {
    "name": "DEB-CUENTA",
    "type": "decimal(10,0,unsigned)",
    "description": ""
   }
  ],
  "outputs": [
   {
    "name": "DEB-RESP",
    "type": "text(fixed,2,ebcdic)",
    "description": ""
   }
  ],
  "scenarios": [
   "Scenario: Account not found\n Given no account 9999999999 exists in CUENTAS\n When a debit of 100.00 is requested for account 9999999999\n Then DEB-RESP is '30'\n And no balance is changed"
  ],
  "sources": [
   {
    "file": "cbl/PAGODEB.cbl",
    "line_start": 18,
    "line_end": 23
   }
  ]
 },
 {
  "id": "RULE-002",
  "name": "Debit rejected when account type differs from requested type",
  "category": "validation",
  "priority": "P0",
  "statement": "When the account type stored on the account (CTA-TIPO) is not equal to the type requested in the debit (DEB-TIPO), DEB-RESP is set to '40'.",
  "condition": "Account found AND CTA-TIPO <> DEB-TIPO",
  "action": "Set DEB-RESP = '40'; no debit is made.",
  "inputs": [
   {
    "name": "CTA-TIPO",
    "type": "text(fixed,3,ebcdic)",
    "description": ""
   },
   {
    "name": "DEB-TIPO",
    "type": "text(fixed,3,ebcdic)",
    "description": ""
   }
  ],
  "outputs": [
   {
    "name": "DEB-RESP",
    "type": "text(fixed,2,ebcdic)",
    "description": ""
   }
  ],
  "scenarios": [
   "Scenario: Type mismatch\n Given account 1234567890 exists with CTA-TIPO 'AHO'\n When a debit of 50.00 is requested with DEB-TIPO 'COR'\n Then DEB-RESP is '40'\n And the balance is unchanged"
  ],
  "sources": [
   {
    "file": "cbl/PAGODEB.cbl",
    "line_start": 24,
    "line_end": 25
   }
  ]
 },
 {
  "id": "RULE-003",
  "name": "Debit rejected when account is not active",
  "category": "validation",
  "priority": "P0",
  "statement": "When the account is not active (NOT CTA-ACTIVA), DEB-RESP is set to '10'.",
  "condition": "Account found AND CTA-TIPO = DEB-TIPO AND NOT CTA-ACTIVA",
  "action": "Set DEB-RESP = '10'; no debit is made.",
  "inputs": [
   {
    "name": "CTA-ESTADO",
    "type": "text(fixed,1,ebcdic)",
    "description": ""
   }
  ],
  "outputs": [
   {
    "name": "DEB-RESP",
    "type": "text(fixed,2,ebcdic)",
    "description": ""
   }
  ],
  "scenarios": [
   "Scenario: Inactive account\n Given account 1234567890 exists, the type matches, and the account is not active\n When a debit of 50.00 is requested\n Then DEB-RESP is '10'\n And the balance is unchanged"
  ],
  "sources": [
   {
    "file": "cbl/PAGODEB.cbl",
    "line_start": 26,
    "line_end": 27
   }
  ]
 },
 {
  "id": "RULE-004",
  "name": "Debit rejected for insufficient funds",
  "category": "validation",
  "priority": "P0",
  "statement": "When CTA-SALDO is strictly less than DEB-MONTO, the debit is rejected by setting DEB-RESP to '20'. A debit equal to the balance is not rejected by this check.",
  "condition": "Account found, type matches, account active AND CTA-SALDO < DEB-MONTO",
  "action": "Set DEB-RESP = '20'; no debit is made.",
  "inputs": [
   {
    "name": "CTA-SALDO",
    "type": "decimal(13,2,signed)",
    "description": ""
   },
   {
    "name": "DEB-MONTO",
    "type": "decimal(13,2,signed)",
    "description": ""
   }
  ],
  "outputs": [
   {
    "name": "DEB-RESP",
    "type": "text(fixed,2,ebcdic)",
    "description": ""
   }
  ],
  "scenarios": [
   "Scenario: Insufficient balance\n Given an active account with CTA-SALDO 100.00 and a matching type\n When a debit of 100.01 is requested\n Then DEB-RESP is '20'\n And the balance stays 100.00",
   "Scenario: Balance equal to amount is allowed\n Given an active account with CTA-SALDO 100.00 and a matching type\n When a debit of 100.00 is requested\n Then the debit proceeds"
  ],
  "sources": [
   {
    "file": "cbl/PAGODEB.cbl",
    "line_start": 28,
    "line_end": 29
   }
  ]
 },
 {
  "id": "RULE-005",
  "name": "Successful debit reduces balance",
  "category": "calculation",
  "priority": "P0",
  "statement": "When none of the preceding WHEN branches of the evaluation apply (WHEN OTHER), the debit amount DEB-MONTO is subtracted from CTA-SALDO, the CUENTAS record is rewritten from CTA-REGISTRO, and DEB-RESP is set to '00'.",
  "condition": "None of the rejection conditions ('30','40','10','20') apply",
  "action": "CTA-SALDO = CTA-SALDO - DEB-MONTO; REWRITE the CUENTAS record; DEB-RESP = '00'.",
  "inputs": [
   {
    "name": "CTA-SALDO",
    "type": "decimal(13,2,signed)",
    "description": ""
   },
   {
    "name": "DEB-MONTO",
    "type": "decimal(13,2,signed)",
    "description": ""
   }
  ],
  "outputs": [
   {
    "name": "CTA-SALDO",
    "type": "decimal(13,2,signed)",
    "description": ""
   },
   {
    "name": "DEB-RESP",
    "type": "text(fixed,2,ebcdic)",
    "description": ""
